`timescale 1ns/1ps
// QW-SLICE6 lockstep-bench copies of rtl/test/full_sm_service/sram_models.sv, rtl/test/hbm_rf_visibility/scale_sram_model.sv
// and rtl/test/qwen_dv/safe_storage/sram_model.sv: the same models, but a read/write collision is NOT fatal (the read returns
// the old word, deterministic on both lockstep sides): random stimulus collides by design.  GENERATED by run_s5.sh eq.
// Functional one-cycle macro models only; no corner/timing/abstract qualification.
module ot_sram_1r1w_128x256_m1_r2c2 (
 input wire clk,r_ce_in,w_ce_in,input wire [6:0] r_addr_in,w_addr_in,
 output reg [255:0] rd_out,input wire [255:0] wd_in,w_mask_in,
 input wire [1:0] rr_en,cr_en,input wire [11:0] rr_addr,input wire [15:0] cr_sel
);
 reg [255:0] mem[0:127];
 always @(posedge clk) begin
  if(r_ce_in && w_ce_in && r_addr_in==w_addr_in) begin end;
  if(r_ce_in) rd_out<=mem[r_addr_in];
  if(w_ce_in) mem[w_addr_in]<=(wd_in & w_mask_in)|(mem[w_addr_in] & ~w_mask_in);
 end
endmodule
